	private String transform(String stylesheetName, String xml, String infoXml) throws Exception {
		Files.writeString(tempDir.resolve("info"), infoXml, StandardCharsets.UTF_8);
		Path xmlPath = tempDir.resolve(stylesheetName + ".xml");
		Files.writeString(xmlPath, xml, StandardCharsets.UTF_8);

		Transformer transformer = newTransformer(stylesheetName);
		StringWriter html = new StringWriter();
		transformer.transform(new StreamSource(xmlPath.toFile()), new StreamResult(html));
		return html.toString();
	}

	private static Transformer newTransformer(String stylesheetName) throws Exception {
		TransformerFactory factory = TransformerFactory.newInstance();
		Path stylesheetPath = Path.of("src/main/webapp/transformations", stylesheetName);
		StreamSource stylesheet = new StreamSource(stylesheetPath.toFile());
		stylesheet.setSystemId(stylesheetPath.toUri().toString());
		Templates templates = factory.newTemplates(stylesheet);
		return templates.newTransformer();
	}

